export type TextureRow = {
	name: string,
	/**  What the texture is for: "base color", "normal" and so on. */
	uses: string[],
	width: number | null,
	height: number | null,
	bytes: number | null,
	/**  `KTX2 ETC1S`, `KTX2 UASTC`, `PNG`, `JPEG`, `WebP` or `Unknown`. */
	codec: string,
	gpuBytes: number | null,
};

export type TextureSize = "1K" | "2K" | "4K";

/**  Where a model's thumbnail stands. */
export type ThumbState = 
/**  The PNG exists. */
"ready" | 
/**  A Blender render is queued or running. */
"rendering" | 
/**
 *  No render will come (Blender is missing or the render failed): the
 *  web view snapshots its own preview and stores that.
 */
"fallback";

/**
 *  A model's thumbnail finished, or will not come from Blender (`state` is
 *  fallback, so the web view stores a snapshot of its own preview). With
 *  `project`, a Board asset now shows it.
 */
export type ThumbnailReady = {
	file: string,
	thumbnail: string | null,
	state: ThumbState,
	project: ProjectManifest | null,
};

export type ToolId = "blender" | "codex" | "ffmpeg" | "toktx" | "gltf-transform" | "node";

export type ToolReport = {
	id: ToolId,
	label: string,
	required: boolean,
	status: ToolStatus,
	source: ToolSource | null,
	path: string | null,
	version: string | null,
	detail: string | null,
	hint: string | null,
	/**
	 *  Set when the tool works but needs attention, for example Codex CLI
	 *  that is not signed in, or an override that no longer exists.
	 */
	warning: string | null,
};

export type ToolSource = "override" | "path" | "known-location" | "npx";

export type ToolStatus = "found" | "missing" | 
/**  A binary exists but `--version` failed or timed out. */
"broken";

/**  The mesh a provider makes: triangles or quads. */
export type Topology = "triangle" | "quad";

export type TripoGeometryQuality = "standard" | "detailed";

/**  One Tripo preset. A character preset also rigs and animates. */
export type TripoPreset = {
	/**  A Tripo model id from the catalog, for example `v3.1-20260211`. */
	model: string,
	/**  The face budget; 0 lets Tripo pick (adaptive). */
	faceLimit: number,
	texture: boolean,
	pbr: boolean,
	textureQuality: TripoTextureQuality,
	/**  Ultra geometry. H3.0 and newer only. */
	geometryQuality: TripoGeometryQuality,
	/**  Clean hand made style low poly topology. H series only. */
	smartLowPoly: boolean,
	/**  Scales the model to real world size in metres. */
	autoSize: boolean,
	/**  Lets Tripo clean up the input image first. */
	imageAutofix: boolean,
	/**  Several images go to the multiview endpoint, front first. */
	multiView: boolean,
	/**  Rig check, then rig, then retarget the animations. */
	rig: boolean,
	/**  A Tripo rig model id from the catalog. */
	rigModel: string,
	rigSpec: TripoRigSpec,
	/**  Preset animation ids, for example `preset:idle`. At most 5. */
	animations: string[],
};

export type TripoPresets = {
	prop: TripoPreset,
	character: TripoPreset,
};

/**  The bone naming a Tripo rig uses. */
export type TripoRigSpec = "mixamo" | "tripo";

export type TripoTextureQuality = "standard" | "detailed" | "extreme";

export type WorkspaceConfig = {
	version: number,
	layout: FolderLayout,
	providers: ProviderSettings,
	budgets: Budgets,
	compression: Compression,
	agents: AgentSettings,
	lab: LabSettings,
	currentProject: string | null,
};

/**  The open workspace as the UI sees it. */
export type WorkspaceSnapshot = {
	root: string,
	display: string,
	config: WorkspaceConfig,
	project: ProjectManifest | null,
	projects: ProjectManifest[],
};

/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

